package com.yuegang.zhihui.inventory.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.inventory.application.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/inventory")public final class InventoryController{private final InventoryService service;public InventoryController(InventoryService s){service=s;}@GetMapping("/{sku}")ApiResponse<InventoryView>get(@PathVariable String sku,HttpServletRequest r){return ok(service.get(sku),r);}@PostMapping("/adjust")ApiResponse<InventoryView>adjust(@Valid @RequestBody InventoryCommand c,HttpServletRequest r){return ok(service.adjust(c),r);}@PostMapping("/reserve")ApiResponse<InventoryView>reserve(@Valid @RequestBody InventoryCommand c,HttpServletRequest r){return ok(service.reserve(c),r);}@PostMapping("/confirm")ApiResponse<InventoryView>confirm(@Valid @RequestBody InventoryCommand c,HttpServletRequest r){return ok(service.confirm(c),r);}@PostMapping("/release")ApiResponse<InventoryView>release(@Valid @RequestBody InventoryCommand c,HttpServletRequest r){return ok(service.release(c),r);}private static<T>ApiResponse<T>ok(T d,HttpServletRequest r){return ApiResponse.success(d,TraceIdResolver.resolve(r));}}
